using System.Windows;using System.Windows.Controls;using LibraryManager.Services;using LibraryManager.Models;namespace LibraryManager.Views;public partial class LoanReturnView:UserControl{LoanService svc=new();DataGrid grid;public LoanReturnView(){InitializeComponent();var p=VH.Page(Root,"امانت‌های جاری");grid=VH.Table(p,svc.Active());p.Children.Add(VH.Btn("بازگرداندن کتاب",(s,e)=>{if(grid.SelectedItem is Loan l){var w=new ReturnConfirmDialog(l);if(w.ShowDialog()==true){try{svc.Return(l.Id,w.Method,w.PayNow);grid.ItemsSource=svc.Active();}catch(Exception ex){VH.Error(ex);}}}}));}}